-- Function: public.fn_get_low_child_care_supplies_by_branch
-- Backup generated on 2026-10-25 20:33:29

CREATE OR REPLACE FUNCTION public.fn_get_low_child_care_supplies_by_branch(p_tenant_id uuid, p_branch_id uuid)  RETURNS TABLE(id uuid, tenant_id uuid, organization_id uuid, branch_id uuid, classroom_id uuid, child_id uuid, supply_type character varying, status character varying, notes text, threshold_note character varying, last_reported_by_user_id uuid, last_reported_by_name character varying, parent_reminder_sent boolean, last_reminder_at timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone, child_name text, classroom_name character varying)  LANGUAGE sql  STABLE AS $function$     SELECT s.id, s.tenant_id, s.organization_id, s.branch_id, s.classroom_id, s.child_id,            s.supply_type, s.status, s.notes, s.threshold_note, s.last_reported_by_user_id,            s.last_reported_by_name, s.parent_reminder_sent, s.last_reminder_at, s.created_at, s.updated_at,            CONCAT(c.first_name, ' ', c.last_name) AS child_name,            cl.name AS classroom_name     FROM child_care_supplies s     JOIN children c ON s.child_id = c.id     LEFT JOIN classrooms cl ON s.classroom_id = cl.id     WHERE s.tenant_id = p_tenant_id        AND s.branch_id = p_branch_id        AND s.status IN ('Low', 'Depleted')     ORDER BY s.updated_at DESC; $function$ ;
